    ok,
    verdict: ok ? VERDICTS.VERIFIED_EXACT : VERDICTS.REFUSED,
    statement: ok ? VERIFIED_STATEMENT : null,
    manifestHash: ctx.manifest.manifestHash,
    txId: ctx.manifest.transaction.txId,
    checks,
    failures: allFailures
