const { normalizeHex } = require("./vault-state");

const NATIVE_SUBNETWORK = "00".repeat(20);

function fail(message) {
  throw new Error(`frozen-tx-v3: ${message}`);
}

function normalizeTxId(value, field) {
  return normalizeHex(value, 32, field);
}

