    verdict: null,
    statement: null,
    refusal: null,
    context: null,
    manifestHash: null,
    txId: null,
    network: null,
    organization: null,
    authorization: null,
    quorum: null,
    ownerSet: null,
    rootState: null,
    timeLock: null,
    freshness: null,
    fee: null,
    vaultOperations: null,
    warnings: null,
    verification: null
