  ROOTED_HD_VAULT_MANIFEST_VERSION_1,
  CONTRACT_VERSION_V7_HD,
  HD_ACTIONS,
  VERIFIED_STATEMENT,
  HD_EXPLANATION,
  buildRootedHdVaultManifestV7,
  verifyRootedHdVaultManifestV7
