    verdict: null,
    statement: null,
    refusal: null,
    manifestHash: null,
    txId: null,
    network: null,
    vault: null,
    action: null,
    ancestorChain: null,
    effectiveAuthority: null,
    delegation: null,
    payment: null,
    expiryStatement: null,
