    level: entry.level,
    pk: l.pk,
    maxPerSpend: l.maxPerSpend,
    periodBudget: l.periodBudget,
    periodSpent: l.periodSpent,
    periodLengthDaa: l.periodLengthDaa,
    periodStartDaa: l.periodStartDaa,
    maxFeePerTx: l.maxFeePerTx,
    maxCarryKas: l.maxCarryKas,
